{"content":"import { Canvas, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { OrbitControls } from '@react-three/drei';
import { useEffect, useMemo } from 'react';
import Table from './Table';
import Balls from './Balls';
import CueStick from './CueStick';
import AimLine from './AimLine';
import PhysicsWorld from '../physics/PhysicsWorld';
import useSettleDetector from '../hooks/useSettleDetector';
import useShotSequence from '../hooks/useShotSequence';
import { useAimStore } from '../store/aimStore';
import {
  CAMERA_DEFAULT_POSITION,
  CAMERA_FOV,
  HALF_LENGTH,
  HALF_WIDTH,
  FLOOR_Y,
} from '../constants/table';

/**
 * Wrapper for game hooks that must run inside the Canvas/Physics context.
 */
function GameHooks() {
  useSettleDetector();
  useShotSequence();
  return null;
}

/**
 * Keeps the R3F camera reference on `window.__r3f_camera` so that
 * useShotSequence (which runs outside of `<Canvas>`) can access the
 * current camera for raycasting.
 */
function CameraRefSync() {
  const { camera } = useThree();
  useEffect(() => {
    (window as any).__r3f_camera = camera;
  }, [camera]);
  return null;
}

/**
 * When in top-down mode we need an orthographic camera that covers the
 * full table.  This component listens to `cameraMode` and imperatively
 * switches the R3F camera between the default perspective camera and a
 * suitable orthographic camera.
 */
function CameraSwitcher() {
  const cameraMode = useAimStore((s) => s.cameraMode);
  const { size, set } = useThree();

  // Build the orthographic camera once (memoised).
  const orthoCamera = useMemo(() => {
    // We want the orthographic frustum to tightly fit the table with a
    // small margin.  Because we are looking straight down the visible
    // width corresponds to X (table short dimension) and visible height
    // to Z (table long dimension).
    const margin = 0.3;
    const halfW = HALF_WIDTH + margin;
    const halfH = HALF_LENGTH + margin;

    // Compute frustum so that the table fills the viewport regardless of
    // aspect ratio.  We base the ortho extents on the larger dimension.
    const aspect = size.width / size.height;
    let left: number, right: number, top: number, bottom: number;
    if (aspect >= 1) {
      // Landscape – width is ample, fit height to table length
      bottom = -halfH;
      top = halfH;
      left = -halfH * aspect;
      right = halfH * aspect;
    } else {
      // Portrait – fit width to table width
      left = -halfW;
      right = halfW;
      bottom = -halfW / aspect;
      top = halfW / aspect;
    }

    const cam = new THREE.OrthographicCamera(
      left,
      right,
      top,
      bottom,
      0.01,
      50,
    );
    cam.position.set(0, 3, 0); // well above the table
    cam.lookAt(0, 0, 0);
    return cam;
  }, [size.width, size.height]);

  useEffect(() => {
    if (cameraMode === 'topdown') {
      orthoCamera.position.set(0, 3, 0);
      orthoCamera.lookAt(0, 0, 0);
      orthoCamera.updateProjectionMatrix();
      set({ camera: orthoCamera });
    } else {
      // Switch back to a fresh perspective camera matching the Canvas default
      const perspCam = new THREE.PerspectiveCamera(
        CAMERA_FOV,
        size.width / size.height,
        0.01,
        50,
      );
      perspCam.position.set(
        CAMERA_DEFAULT_POSITION[0],
        CAMERA_DEFAULT_POSITION[1],
        CAMERA_DEFAULT_POSITION[2],
      );
      perspCam.lookAt(0, 0, 0);
      perspCam.updateProjectionMatrix();
      set({ camera: perspCam });
    }
  }, [cameraMode, orthoCamera, set, size.width, size.height]);

  return null;
}

/**
 * R3F Canvas with PCFSoftShadowMap (2048×2048), perspective camera (45 deg FOV)
 * positioned above the table at an angle, ambient + directional + point lights,
 * and OrbitControls constrained so the user cannot go below the table.
 *
 * Phase 8 (T25): shadow map upgraded to PCFSoftShadowMap for soft shadow edges,
 * directional light shadow camera covers the full table area, balls cast shadows
 * onto the felt surface.
 */
export default function Scene() {
  const cameraMode = useAimStore((s) => s.cameraMode);
  const orbitTarget: [number, number, number] = [0, 0, 0];

  return (
    <Canvas
      shadows
      gl={{
        shadowMap: {
          enabled: true,
          type: THREE.PCFSoftShadowMap,
